CREATE TABLE app_user (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE access_token (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES app_user(id) ON DELETE CASCADE);
CREATE TABLE device (id VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL, name VARCHAR(80) NOT NULL, secret_hash VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(owner_id) REFERENCES app_user(id));
CREATE TABLE device_session (id VARCHAR(36) NOT NULL, device_id VARCHAR(64) NOT NULL, first_seen TIMESTAMP(6) NOT NULL, last_seen TIMESTAMP(6) NOT NULL, PRIMARY KEY(device_id,id), FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
CREATE TABLE telemetry_batch (id VARCHAR(36) PRIMARY KEY, device_id VARCHAR(64) NOT NULL, session_id VARCHAR(36) NOT NULL, sequence_no BIGINT NOT NULL, measured_at TIMESTAMP(6), received_at TIMESTAMP(6) NOT NULL, source VARCHAR(16) NOT NULL, payload TEXT NOT NULL, UNIQUE(device_id,session_id,sequence_no), FOREIGN KEY(device_id,session_id) REFERENCES device_session(device_id,id) ON DELETE CASCADE, CHECK(sequence_no >= 0));
CREATE INDEX idx_telemetry_history ON telemetry_batch(device_id,received_at);
CREATE INDEX idx_telemetry_measured ON telemetry_batch(device_id,measured_at);
CREATE TABLE health_reading (batch_id VARCHAR(36) PRIMARY KEY, heart_rate_bpm DOUBLE, spo2_percent DOUBLE, quality VARCHAR(24) NOT NULL, FOREIGN KEY(batch_id) REFERENCES telemetry_batch(id) ON DELETE CASCADE);
CREATE TABLE motion_reading (batch_id VARCHAR(36) PRIMARY KEY, magnitude_g DOUBLE, pitch_deg DOUBLE, roll_deg DOUBLE, activity VARCHAR(16) NOT NULL, fall_state VARCHAR(16) NOT NULL, FOREIGN KEY(batch_id) REFERENCES telemetry_batch(id) ON DELETE CASCADE);
CREATE TABLE gps_reading (batch_id VARCHAR(36) PRIMARY KEY, has_fix BOOLEAN NOT NULL, latitude DOUBLE, longitude DOUBLE, satellites INTEGER, FOREIGN KEY(batch_id) REFERENCES telemetry_batch(id) ON DELETE CASCADE);
CREATE TABLE alert (id VARCHAR(36) PRIMARY KEY, device_id VARCHAR(64) NOT NULL, batch_id VARCHAR(36), kind VARCHAR(32) NOT NULL, severity VARCHAR(16) NOT NULL, source VARCHAR(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL, UNIQUE(batch_id,kind), FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE, FOREIGN KEY(batch_id) REFERENCES telemetry_batch(id) ON DELETE SET NULL);
CREATE INDEX idx_alert_device_time ON alert(device_id,created_at);
CREATE TABLE alert_acknowledgement (alert_id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, acknowledged_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(alert_id) REFERENCES alert(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE device_configuration (device_id VARCHAR(64) PRIMARY KEY, revision BIGINT NOT NULL, telemetry_interval_ms INTEGER NOT NULL DEFAULT 1000, timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata', FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE, CHECK(telemetry_interval_ms BETWEEN 1000 AND 60000));
CREATE TABLE synchronization_state (device_id VARCHAR(64) NOT NULL, session_id VARCHAR(36) NOT NULL, highest_sequence BIGINT NOT NULL, updated_at TIMESTAMP(6) NOT NULL, PRIMARY KEY(device_id,session_id), FOREIGN KEY(device_id,session_id) REFERENCES device_session(device_id,id) ON DELETE CASCADE);
